{
  "name": "CogniQ - AI Powered IQ Test",
  "description": "An advanced IQ assessment tool that uses Gemini AI to generate unique logic, verbal, and mathematical reasoning questions to estimate your IQ and analyze your cognitive strengths."
}

export enum QuestionCategory {
  LOGICAL = 'Logical Reasoning',
  NUMERICAL = 'Numerical Intelligence',
  VERBAL = 'Verbal Intelligence',
  SPATIAL = 'Spatial Reasoning'
}

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctIndex: number;
  category: QuestionCategory;
  difficulty: number; // 1-5
}

export interface UserAnswer {
  questionId: number;
  selectedOptionIndex: number;
  timeTakenSeconds: number;
}

export interface QuizResult {
  iqScore: number;
  percentile: number;
  correctCount: number;
  totalQuestions: number;
  categoryBreakdown: {
    category: string;
    score: number; // 0-100
    fullMark: number;
  }[];
  analysis: string;
}

export type AppState = 'intro' | 'generating' | 'quiz' | 'analyzing' | 'result' | 'error';

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Question, QuestionCategory, QuizResult, UserAnswer } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const QUESTIONS_COUNT = 10;

// Schema for generating questions
const questionSchema: Schema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      text: { type: Type.STRING, description: "The question text. e.g., 'Which number completes the sequence?'" },
      options: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        description: "An array of 4 possible answers."
      },
      correctIndex: { type: Type.INTEGER, description: "The index (0-3) of the correct answer." },
      category: {
        type: Type.STRING,
        enum: [
          QuestionCategory.LOGICAL,
          QuestionCategory.NUMERICAL,
          QuestionCategory.VERBAL,
          QuestionCategory.SPATIAL
        ]
      },
      difficulty: { type: Type.INTEGER, description: "Difficulty level from 1 (Easy) to 5 (Genius)." }
    },
    required: ["text", "options", "correctIndex", "category", "difficulty"]
  }
};

export const generateQuizQuestions = async (): Promise<Question[]> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `Generate ${QUESTIONS_COUNT} unique, challenging, and high-quality IQ test questions. 
    Mix the categories: Logical Reasoning, Numerical Intelligence, Verbal Intelligence, and Spatial Reasoning.
    Ensure the questions vary in difficulty (1-5).
    For spatial questions, describe the visual scenario clearly in text (e.g., 'If you fold a cube...').
    Ensure there is strictly only one correct answer per question.`;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        temperature: 0.7 // slightly creative but logical
      }
    });

    const rawData = response.text;
    if (!rawData) throw new Error("No data received from Gemini");

    const parsedData = JSON.parse(rawData);

    return parsedData.map((q: any, index: number) => ({
      ...q,
      id: index
    }));

  } catch (error) {
    console.error("Error generating questions:", error);
    throw error;
  }
};

export const analyzeIQ = async (questions: Question[], answers: UserAnswer[]): Promise<QuizResult> => {
  // Calculate raw stats locally first
  let correctCount = 0;
  const categoryScores: Record<string, { correct: number; total: number }> = {};

  questions.forEach((q) => {
    if (!categoryScores[q.category]) {
      categoryScores[q.category] = { correct: 0, total: 0 };
    }
    categoryScores[q.category].total += 1;

    const answer = answers.find(a => a.questionId === q.id);
    if (answer && answer.selectedOptionIndex === q.correctIndex) {
      correctCount++;
      categoryScores[q.category].correct += 1;
    }
  });

  // Basic formula for "Game IQ": 
  // Baseline 75 + (Accuracy % * 85) + Bonus for difficulty
  // This is pseudo-science for the game, simplified.
  const accuracy = correctCount / questions.length;
  // Weighted score based on difficulty could be added here, simplified for now
  const calculatedIQ = Math.round(75 + (accuracy * 85)); 

  // Format for Recharts
  const categoryBreakdown = Object.keys(categoryScores).map(cat => ({
    category: cat,
    score: Math.round((categoryScores[cat].correct / categoryScores[cat].total) * 100) || 0,
    fullMark: 100
  }));

  // AI Analysis of performance
  let analysisText = "Could not generate analysis.";
  try {
    const model = "gemini-3-flash-preview";
    const performanceSummary = questions.map(q => {
      const ans = answers.find(a => a.questionId === q.id);
      const isCorrect = ans?.selectedOptionIndex === q.correctIndex;
      return `Category: ${q.category}, Difficulty: ${q.difficulty}, Correct: ${isCorrect}, Time: ${ans?.timeTakenSeconds}s`;
    }).join('\n');

    const prompt = `Analyze this IQ test performance data to provide a short, encouraging but professional psychological profile (max 3 sentences). 
    The user scored an estimated IQ of ${calculatedIQ}.
    Data:
    ${performanceSummary}`;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    if (response.text) {
      analysisText = response.text;
    }
  } catch (e) {
    console.error("Analysis generation failed", e);
    analysisText = "Great effort! Your score indicates strong potential.";
  }

  return {
    iqScore: calculatedIQ,
    percentile: calculatePercentile(calculatedIQ), // Mock function
    correctCount,
    totalQuestions: questions.length,
    categoryBreakdown,
    analysis: analysisText
  };
};

function calculatePercentile(iq: number): number {
  // Simple normal distribution approximation for mean=100, sd=15
  if (iq < 70) return 2;
  if (iq < 85) return 16;
  if (iq < 100) return 50;
  if (iq < 115) return 84;
  if (iq < 130) return 98;
  return 99.9;
}

