import React, { useState, useEffect, useRef } from 'react';
import { AppState, Question, UserAnswer, QuizResult } from './types';
import { generateQuizQuestions, analyzeIQ } from './services/geminiService';
import { LoadingSpinner } from './components/LoadingSpinner';
import { Button } from './components/Button';
import { QuizCard } from './components/QuizCard';
import { SkillsRadar } from './components/RadarChart';
import { Brain, ChevronRight, Activity, Clock, Award, Play } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('intro');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [result, setResult] = useState<QuizResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);

  // Timing refs
  const questionStartTime = useRef<number>(0);

  const startQuiz = async () => {
    setAppState('generating');
    setError(null);
    try {
      const qs = await generateQuizQuestions();
      setQuestions(qs);
      setCurrentQuestionIndex(0);
      setUserAnswers([]);
      setAppState('quiz');
      questionStartTime.current = Date.now();
    } catch (e) {
      console.error(e);
      setError("Failed to generate test. Please verify your API Key or try again.");
      setAppState('error');
    }
  };

  const handleNextQuestion = () => {
    if (selectedOption === null) return;

    const timeTaken = (Date.now() - questionStartTime.current) / 1000;
    const newAnswer: UserAnswer = {
      questionId: questions[currentQuestionIndex].id,
      selectedOptionIndex: selectedOption,
      timeTakenSeconds: timeTaken
    };

    const newAnswers = [...userAnswers, newAnswer];
    setUserAnswers(newAnswers);
    setSelectedOption(null);

    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      questionStartTime.current = Date.now();
    } else {
      finishQuiz(newAnswers);
    }
  };

  const finishQuiz = async (answers: UserAnswer[]) => {
    setAppState('analyzing');
    try {
      const analysisResult = await analyzeIQ(questions, answers);
      setResult(analysisResult);
      setAppState('result');
    } catch (e) {
      console.error(e);
      setError("Failed to analyze results.");
      setAppState('error');
    }
  };

  // Render Helpers
  const renderIntro = () => (
    <div className="max-w-2xl mx-auto text-center px-4">
      <div className="mb-8 inline-block p-4 bg-indigo-500/10 rounded-full">
        <Brain className="w-16 h-16 text-indigo-400" />
      </div>
      <h1 className="text-4xl md:text-6xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-300 via-purple-300 to-indigo-300 mb-6 pb-2">
        CogniQ
      </h1>
      <p className="text-xl text-slate-300 mb-8 leading-relaxed">
        Discover your cognitive potential with our AI-powered IQ assessment.
        We test logical, numerical, verbal, and spatial reasoning in a uniquely generated session.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-12 text-slate-400 text-sm">
        <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
          <Activity className="w-6 h-6 mx-auto mb-2 text-emerald-400" />
          <p>Adaptive Difficulty</p>
        </div>
        <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
          <Brain className="w-6 h-6 mx-auto mb-2 text-purple-400" />
          <p>Multi-dimensional</p>
        </div>
        <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
          <Clock className="w-6 h-6 mx-auto mb-2 text-amber-400" />
          <p>Instant Analysis</p>
        </div>
      </div>

      <Button onClick={startQuiz} size="lg" className="w-full md:w-auto shadow-indigo-500/50">
        <Play className="w-5 h-5 mr-2" />
        Start Assessment
      </Button>
    </div>
  );

  const renderQuiz = () => (
    <div className="w-full max-w-4xl mx-auto px-4 flex flex-col h-full justify-between pb-8">
      {/* Header */}
      <div className="mb-8">
        <div className="flex justify-between items-end mb-2">
          <h2 className="text-lg text-slate-400 font-medium">Question {currentQuestionIndex + 1} <span className="text-slate-600">/ {questions.length}</span></h2>
          <div className="text-indigo-400 text-sm font-semibold">
            {Math.round(((currentQuestionIndex) / questions.length) * 100)}% Complete
          </div>
        </div>
        <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-indigo-500 to-purple-500 transition-all duration-500 ease-out"
            style={{ width: `${((currentQuestionIndex) / questions.length) * 100}%` }}
          />
        </div>
      </div>

      {/* Card */}
      <div className="flex-grow flex items-center justify-center">
        <QuizCard 
          question={questions[currentQuestionIndex]}
          selectedOption={selectedOption}
          onSelectOption={setSelectedOption}
        />
      </div>

      {/* Footer */}
      <div className="mt-8 flex justify-end">
        <Button 
          onClick={handleNextQuestion} 
          disabled={selectedOption === null}
          size="lg"
          className="w-full md:w-auto"
        >
          {currentQuestionIndex === questions.length - 1 ? 'Finish Assessment' : 'Next Question'}
          <ChevronRight className="w-5 h-5 ml-2" />
        </Button>
      </div>
    </div>
  );

  const renderResult = () => {
    if (!result) return null;
    return (
      <div className="w-full max-w-4xl mx-auto px-4 animate-fade-in-up">
        <div className="text-center mb-10">
          <Award className="w-16 h-16 mx-auto text-yellow-400 mb-4" />
          <h2 className="text-3xl font-bold text-white mb-2">Assessment Complete</h2>
          <p className="text-slate-400">Here is your cognitive profile breakdown.</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
          {/* Main Score Card */}
          <div className="lg:col-span-1 bg-gradient-to-b from-slate-800 to-slate-900 border border-slate-700 rounded-2xl p-8 flex flex-col items-center justify-center text-center shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500" />
             <p className="text-slate-400 text-sm font-semibold uppercase tracking-widest mb-4">Estimated IQ</p>
             <div className="text-7xl font-bold text-white mb-2 tracking-tighter">
               {result.iqScore}
             </div>
             <p className="text-indigo-400 text-sm mb-6">Top {100 - result.percentile}% of population</p>

             <div className="w-full grid grid-cols-2 gap-4 border-t border-slate-700 pt-6">
                <div>
                   <p className="text-2xl font-bold text-white">{result.correctCount}/{result.totalQuestions}</p>
                   <p className="text-xs text-slate-500">Correct Answers</p>
                </div>
                <div>
                   <p className="text-2xl font-bold text-white">{Math.round((result.correctCount / result.totalQuestions) * 100)}%</p>
                   <p className="text-xs text-slate-500">Accuracy</p>
                </div>
             </div>
          </div>

          {/* Radar Chart */}
          <div className="lg:col-span-2 bg-slate-800/50 border border-slate-700 rounded-2xl p-6 flex flex-col">
            <h3 className="text-lg font-semibold text-white mb-4">Cognitive Breakdown</h3>
            <div className="flex-grow flex items-center justify-center">
               <SkillsRadar data={result.categoryBreakdown} />
            </div>
          </div>
        </div>

        {/* AI Analysis */}
        <div className="bg-indigo-900/20 border border-indigo-500/20 rounded-2xl p-6 md:p-8">
          <div className="flex items-start">
             <Brain className="w-6 h-6 text-indigo-400 mt-1 mr-4 flex-shrink-0" />
             <div>
               <h3 className="text-lg font-semibold text-indigo-200 mb-2">AI Performance Analysis</h3>
               <p className="text-slate-300 leading-relaxed text-sm md:text-base">
                 {result.analysis}
               </p>
             </div>
          </div>
        </div>

        <div className="mt-12 text-center">
           <Button onClick={() => setAppState('intro')} variant="secondary">
             Retake Assessment
           </Button>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center py-12 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
         <div className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] bg-indigo-900/20 rounded-full blur-3xl opacity-30"></div>
         <div className="absolute top-[20%] -right-[10%] w-[60%] h-[60%] bg-purple-900/20 rounded-full blur-3xl opacity-30"></div>
      </div>

      <main className="w-full relative z-10 flex-grow flex flex-col justify-center">
        {appState === 'intro' && renderIntro()}

        {appState === 'generating' && (
          <LoadingSpinner message="Generative AI is crafting your unique test..." />
        )}

        {appState === 'quiz' && renderQuiz()}

        {appState === 'analyzing' && (
           <LoadingSpinner message="Analyzing cognitive patterns and calculating score..." />
        )}

        {appState === 'result' && renderResult()}

        {appState === 'error' && (
           <div className="text-center p-8 bg-red-500/10 border border-red-500/20 rounded-xl max-w-md mx-auto">
             <h3 className="text-red-400 font-bold mb-2">Error Occurred</h3>
             <p className="text-red-200 mb-4">{error}</p>
             <Button onClick={() => setAppState('intro')} variant="outline">Try Again</Button>
           </div>
        )}
      </main>

      <footer className="w-full text-center py-6 text-slate-600 text-xs relative z-10">
        <p>CogniQ is for entertainment and self-improvement purposes only.</p>
        <p>Not a clinical diagnostic tool.</p>
      </footer>
    </div>
  );
};

export default App;

